class Solution:
    def findSecondMinimumValue(self, root: Optional[TreeNode]) -> int:
        vals = set()
        def dfs(node):
            if not node:
                return
            vals.add(node.val)
            dfs(node.left)
            dfs(node.right)
        dfs(root)
        if len(vals) < 2:
            return -1
        return sorted(vals)[1]

