class Solution {
public:
    void dfs(TreeNode* node, set<long long>& vals) {
        if (!node) return;
        vals.insert(node->val);
        dfs(node->left, vals);
        dfs(node->right, vals);
    }
    int findSecondMinimumValue(TreeNode* root) {
        set<long long> vals;
        dfs(root, vals);
        if (vals.size() < 2) return -1;
        auto it = next(vals.begin());
        return *it;
    }
};

