class Solution {
    private TreeSet<Long> vals = new TreeSet<>();
    private void dfs(TreeNode node) {
        if (node == null) return;
        vals.add((long) node.val);
        dfs(node.left);
        dfs(node.right);
    }
    public int findSecondMinimumValue(TreeNode root) {
        dfs(root);
        if (vals.size() < 2) return -1;
        Iterator<Long> it = vals.iterator();
        it.next();
        return it.next().intValue();
    }
}

