class Solution {
public:
    long long minVal, ans = LLONG_MAX;
    void dfs(TreeNode* node) {
        if (!node || node->val >= ans) return;
        if (node->val > minVal) { ans = node->val; return; }
        dfs(node->left);
        dfs(node->right);
    }
    int findSecondMinimumValue(TreeNode* root) {
        minVal = root->val;
        dfs(root);
        return ans == LLONG_MAX ? -1 : (int)ans;
    }
};

